def extend(page: str) -> str:
    page = page.replace('</style>', CSS+'</style>', 1)
    page = page.replace('</aside>', '<form action="/_access/logout" method="post" style="margin:18px 13px 0"><button type="submit" class="mini secondary" style="width:100%">退出访问</button></form></aside>', 1)
    page = page.replace('当前固定首屏 10 条上限，上游可能返回更少。', 'Web 采集首屏；News 返回搜索 RSS 条目；Trends 返回当前话题及相关报道。数量以上游实际返回为准。')
    # Replace only presentational elements, keeping API and form IDs intact.
    mark = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="15" fill="#174ea6"/><text x="32" y="43" text-anchor="middle" fill="white" font-family="Arial,sans-serif" font-size="30" font-weight="700">S</text></svg>'
    favicon = 'data:image/svg+xml;base64,'+base64.b64encode(mark.encode()).decode()
    page = re.sub(r'<link rel="icon"[^>]*>', '<link rel="icon" href="'+favicon+'">', page, count=1)
    page = page.replace('<body>', '<body><a class="skip-link" href="#mainContent">跳到主内容</a>', 1)
    page = page.replace('<aside>', '<aside id="workbenchNav" aria-label="工作台导航"><button id="mobileNavClose" class="icon-button nav-close" type="button" aria-label="关闭导航">'+icon('close')+'</button>',1)
    a=page.index('<div class="brand">');b=page.index('<nav ',a)
    page=page[:a]+'<div class="brand"><span class="brand-mark" aria-hidden="true">S</span><span class="brand-name">SearchFlow<small>数据研究工作台</small></span></div>'+page[b:]
    nav_icons={'overview':'dashboard','tasks':'tasks','results':'dataset','analysis':'analysis','monitors':'monitor','api':'api','whale':'sync','settings':'settings'}
    for key,name in nav_icons.items():
        page=re.sub(r'(<a href="#'+key+r'" data-view="'+key+r'"><span class="nav-icon" aria-hidden="true">).*?(</span>)',lambda m:m[1]+icon(name)+m[2],page,count=1)
    page=page.replace('<nav aria-label="主导航">','<nav aria-label="主导航"><span class="nav-section">数据工作台</span>',1)
    page=page.replace('<a href="#whale" data-view="whale">','<span class="nav-section">工具与设置</span><a href="#whale" data-view="whale">',1)
    page=page.replace('API 中心','API 工具').replace('让你的应用使用搜索数据','API 连接与调试').replace('把搜索数据接入你的产品','配置权限，调用搜索接口与导出结果')
